with enriched as (select *, count(discount) over (partition by store_id, channel order by order_date, id rows between 2 preceding and current row) as last3_count_discount, avg(discount) over (partition by store_id, channel order by order_date, id rows between 2 preceding and current row) as last3_avg_discount, min(discount) over (partition by store_id, channel order by order_date, id rows between 2 preceding and current row) as last3_min_discount, sum(shipping_fee) over (partition by store_id order by order_date, id rows between unbounded preceding and current row) as cumulative_shipping_fee from orders where shipping_fee < 26) select case when shipping_fee >= 43 then 'PREMIUM' else 'STANDARD' end as shipping_fee_tier, date_trunc('quarter', order_date) as quarter_start, percentile_approx(amount, 0.95) as amount_p95, size(collect_set(status)) as num_status, percentile_approx(cumulative_shipping_fee, 0.9) as cumulative_shipping_fee_p90, count(*) filter (where channel = 'partner') as partner_rows from enriched group by case when shipping_fee >= 43 then 'PREMIUM' else 'STANDARD' end, date_trunc('quarter', order_date)
